update public.hub_chk_points set q='Do we follow the pharma marketing code: no gifts, trips or cash to doctors?', why='Yearly self-declaration by the head of the firm is required.', law='UCPMP 2024', evidence='Self-declaration + expense records', updated_at=now() where code='SM01';
update public.hub_chk_points set q='Is there a signed agreement for every distributor and stockist?', why='Supply to an unlicensed party is our offence too.', law='Drugs Rules r.65', evidence='Distributor file', updated_at=now() where code='SM03';
update public.hub_chk_points set q='Do online listings show seller name and address and country of origin?', why='Marketplaces delist non-compliant products.', law='Consumer Protection (E-Commerce) Rules 2020', evidence='Listing screenshots', updated_at=now() where code='SM04';
update public.hub_chk_points set q='Is the Amazon brand registry kept current?', why='A suspended account stops sales overnight.', law='Marketplace policy', evidence='Brand registry status', updated_at=now() where code='SM05';
update public.hub_chk_points set q='Is the customer-care number / email on our packs working?', why='Unanswered complaints go to consumer court.', law='Consumer Protection Act 2019', evidence='Care number test note', updated_at=now() where code='SM06';
